func fib(n: int): int {
    a, b := 0, 1
    for _ in 0..<n {
        a, b = b, a + b
    }
    return a
}

func main() {
    println(fib(10))
    grid := [[1, 2], [3, 4], [5, 6]]
    outer@ for i, row in grid {
        for v in row {
            if v == 4 {
                println("found 4 in row", i)
                break@outer
            }
        }
    }
}

